import boto3
import os

def register_user(email, password):
    client = boto3.client(
        'cognito-idp',
        region_name=os.environ.get('AWS_REGION'),
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY')
    )
    user_pool_id = os.environ.get('COGNITO_USER_POOL_ID')
    client_id = os.environ.get('COGNITO_CLIENT_ID')

    try:
        response = client.sign_up(
            ClientId=client_id,
            SecretHash='',  # Not needed if client secret is not enabled for the app client
            Username=email,
            Password=password,
            UserAttributes=[
                {
                    'Name': 'email',
                    'Value': email
                },
            ]
        )
        return response
    except client.exceptions.UsernameExistsException:
        raise ValueError("User with this email already exists.")
    except Exception as e:
        raise RuntimeError(f"Cognito registration failed: {e}")

import boto3
import os

def email_password_login(email, password):
    client = boto3.client(
        'cognito-idp',
        region_name=os.environ.get('AWS_REGION'),
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY')
    )
    client_id = os.environ.get('COGNITO_CLIENT_ID')

    try:
        response = client.initiate_auth(
            ClientId=client_id,
            AuthFlow='USER_PASSWORD_AUTH',
            AuthParameters={
                'USERNAME': email,
                'PASSWORD': password
            }
        )
        return response
    except client.exceptions.NotAuthorizedException:
        raise ValueError("Incorrect username or password.")
    except Exception as e:
        raise RuntimeError(f"Cognito login failed: {e}")

import boto3
import os

def refresh_session(refresh_token):
    client = boto3.client(
        'cognito-idp',
        region_name=os.environ.get('AWS_REGION'),
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY')
    )
    client_id = os.environ.get('COGNITO_CLIENT_ID')

    try:
        response = client.initiate_auth(
            ClientId=client_id,
            AuthFlow='REFRESH_TOKEN_AUTH',
            AuthParameters={
                'REFRESH_TOKEN': refresh_token
            }
        )
        return response
    except client.exceptions.NotAuthorizedException:
        raise ValueError("Invalid refresh token.")
    except Exception as e:
        raise RuntimeError(f"Cognito session refresh failed: {e}")

import boto3
import os

def password_reset(email):
    client = boto3.client(
        'cognito-idp',
        region_name=os.environ.get('AWS_REGION'),
        aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
        aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY')
    )
    client_id = os.environ.get('COGNITO_CLIENT_ID')

    try:
        response = client.forgot_password(
            ClientId=client_id,
            Username=email,
        )
        return response
    except client.exceptions.UserNotFoundException:
        raise ValueError("User with this email not found.")
    except Exception as e:
        raise RuntimeError(f"Cognito password reset initiation failed: {e}")

